const NAME_HARF = Object.fromEntries([['1222', 'ا ف'], ['2221', 'ب ص'], ['2122', 'ج ق'], ['2212', 'د ر'], ['2211', 'ه ش'], ['1122', 'و ت'], ['2111', 'ز ث'], ['1112', 'ح خ'], ['1121', 'ط ذ'], ['1211', 'ی ض'], ['2121', 'ک ظ'], ['1212', 'ل غ'], ['2222', 'م'], ['1221', 'ن'], ['2112', 'س'], ['1111', 'ع']].map(([c, t]) => [nameOf(c.split('').map(Number)), t.split(' ')]));
const NAME_HARF_ORDER = ['1222', '2221', '2122', '2212', '2211', '1122', '2111', '1112', '1121', '1211', '2121', '1212', '2222', '1221', '2112', '1111'].map(c => nameOf(c.split('').map(Number)));
function nameExtract(){
    const fe = h => [rowsOf(S(h))[0], rowsOf(S(h))[3]];
    let ev = 0; for(let h = 1; h <= 16; h++) fe(h).forEach(r => { if(r === 2) ev += 2; });
    const h1 = ev % 12 || 12;
    let od = 0; for(let h = h1; h <= 16; h++) fe(h).forEach(r => { if(r === 1) od += 1; });
    const h2 = od % 12 || 12;
    const n = dotsOf(S(h1)) + dotsOf(S(h2)), end = ((n - 1) % 16) + 1, h3 = end % 16 + 1;
    const hs = [h1, h2, h3], two = hs.filter(h => NAME_HARF[S(h)].length === 2).length;
    const letters = hs.map(h => { const l = NAME_HARF[S(h)]; return two >= 2 ? l : [l[0]]; });
    return { ev, h1, od, h2, n, end, h3, hs, two, letters };
}

