    const n = K.filter(([x]) => housesOf(x).length).length; out.push(it(`${fa(n)} خادم از ${fa(K.length)} در رمل حاضرند: ${n > K.length / 2 ? 'کار آن خانه یاری دارد و برآید' : 'یاری کم است'}.`, [], n > K.length / 2 ? 'good' : 'mid'));
