    const p10 = plOf(10), W = { 'شمس': 'انتظار ملک دارند', 'مشتری': 'انتظار قاضی و حکم شرعی', 'مریخ': 'انتظار لشکر دیگر' }; if(W[p10]) out.push(it(`دهم «${S(10)}» از اشکال ${p10}: ${W[p10]}.`, [10], 'info'));
