    const s8 = S(8), w8 = in12(s8); out.push(it(`هشتم «${s8}» ${fOf(s8)}، دهم ${fOf(S(10))}: ${fOf(s8) === 'نحس' && fOf(S(10)) === 'نحس' ? 'دزدیده باز ندهند' : fOf(s8) === 'سعد' && fOf(S(10)) === 'سعد' ? 'دزدیده باز دهند' : 'میانه'}؛ ${w8.includes(10) ? 'دزد بیرون شهر است' : 'دزد در شهر است'}.`, [8, 10], 'info'));
