    const s8 = S(8), U = { 'آتش': 'روز', 'باد': 'هفته', 'آب': 'ماه', 'خاک': 'سال' }; out.push(it(`ترس: هشتم «${s8}» ${META[s8].el}ی است: به ${fa(dotsOf(s8))} ${U[META[s8].el]} بگذرد.`, [8], 'info'));
