const SJ_MEANING = ['دیدن و حرارت و فکر تیز و بزرگی جستن', 'سخن و خبر و واسطه شدن کسی', 'پیوستن و اعتدال و زود رسیدن به مراد', 'حصول و ثبات، و خصم و بازدارنده'];
