const MTH = {"لحیان": {"طریق": "نیکویی عاقبت و گشایش کارها و حاصل شدن مراد؛ اگر شکل ثابت در خانه‌ی چهارم باشد، از جای خود نقل می‌کند؛ در دعوی و مناظره بر سر املاک، مال غایب به دست می‌آید؛ همه‌ی کارها به خیر و سلامت است.", "عتبه الداخل": "گشایش کارها؛ اگر سؤال از سفر باشد خسارت مال است؛ فروختن چیزهای حیوانی نیکوست و آنچه گم شده زود به دست می‌آید؛ شرکت را بد است؛ زن خواستن شادی می‌افزاید؛ غایب و معشوق زود به هم می‌رسند.", "جماعت": "خیر و خوبی و گشایش کارها و سود از معامله و شرکت؛ زن خواستن و همنشینی با اهل علم و صلاح؛ دعوی و سوگند به سبب مال، و چیزی که با سوگند به دست می‌آید.", "لحیان": "سفر و حرکتی که در آن راحت باشد؛ اگر سؤال از غایب باشد زود به هم می‌رسند و معشوق حاصل می‌شود؛ شرکت و نکاح را نیکوست؛ اما از بهر فرزندان دلتنگی هست.", "حمره": "گرفتن زر و سیم و دست زدن به کار بزرگان؛ اگر چیزی گم شده باشد به دست می‌آید؛ در خرید و فروش اسب و گوسفند خیر و راحت است؛ با زنان و شریکان خصومت و نزاع پیش می‌آید.", "نصره الخارج": "گشایش کارها و کسب، و راحت و قوت از طرف بزرگان؛ روزی گشاده می‌شود و مراد و امید حاصل است؛ اگر سؤال از چیز گم‌شده باشد به دست می‌آید.", "اجتماع": "بیرون رفتن مال، و آگاه شدن از احوال و پیروزی در کارها؛ مراد از طرف بزرگان حاصل می‌شود؛ میان زنان و شریکان خصومت است؛ کارهای پنهان آشکار می‌شود.", "عتبه الخارج": "سفر دور و راحت و ایمنی در آن سفر؛ اگر سؤال از غایب باشد به سلامت است و عاقبت بازمی‌آید؛ در معامله‌ی حیوان و چیزهای نیک سود می‌برد.", "بیاض": "خبر کارها و به مراد رسیدن و بازآمدن دوستان غایب؛ دلتنگی از سوی بزرگان و زیان مالی که در دست شریکان است؛ اگر سؤال از مقصود و مراد باشد زود حاصل می‌شود و از ترس و اندوه ایمن است.", "قبض الخارج": "سفری با فایده و به کام دل رسیدن؛ خریدن ملک و سود از معامله‌ی غلام و کنیز؛ خریدن بهتر از فروختن است؛ اگر سؤال از بیمار باشد رنجش دراز می‌کشد و بیم هست؛ از سوی بزرگان راحت می‌بیند.", "عقله": "غم و اندوه از سوی زنان، یا کسی که در غم گرفتار است؛ جنگ و خصومت و دعوی به سبب مال؛ مال غایب به دست پادشاه می‌افتد؛ در پایان کار راحت و ایمن است.", "انکیس": "بستگی کار و کسب و بدحالی غایب و دل کندن از دوستان؛ از سوی زنان فتنه است؛ اگر سؤال از بیمار باشد بیم مرگ هست؛ مال گریخته و گم‌شده دیر به دست می‌آید.", "قبض الداخل": "نیکویی حال و گشایش کار و کسب و به مقصود رسیدن از سوی دوستان و شرکت و معامله و ازدواج؛ روز آدینه به مراد می‌رسد و معشوق را می‌یابد؛ از شخصی سپیدپوست دشمنی می‌بیند.", "فرح": "خیر و خوبی و رسیدن به امیدها از همه نوع؛ اگر سؤال از نکاح باشد نیکوست؛ در سفر مال به دست می‌آید و با معشوق عهد می‌بندد و راحت می‌یابد؛ این مثلثه سعد مطلق است.", "نقی الخد": "مشغولی از سوی زنان؛ دشمنی که قصد مال دارد؛ غلام و کنیز یا چهارپایی به دست می‌آید؛ چهارشنبه یا پنجشنبه از احوال غایب خبر می‌رسد؛ سفر را نیک است ولی مال دیر می‌آید.", "نصره الداخل": "سفر و حرکت و گرفتن مال از چیزی چون بهای حیوان؛ زیان مال: زنی یا مردی قصد مال می‌کند؛ اگر سؤال از غایب باشد زود می‌رسد و با دوستان جمع می‌شود؛ بیماری دراز می‌کشد."}, "نقی الخد": {"لحیان": "نیکویی عاقبت کار و گشایش کسب و نکاح و سفر و گرفتن مال؛ اگر سؤال از غایب باشد سالم است و از دیدار دوستان شاد می‌شود؛ شب پنجشنبه از ضمیر آگاه می‌شود.", "نصره الداخل": "خیر و خوبی و رسیدن به امید و مقصود از هر نوع؛ اگر سؤال از غایب باشد به یاری دوستان زود به مقصود می‌رسد؛ گم‌شده و گریخته به دست می‌آید؛ حامله و زندانی زود رها می‌شوند.", "بیاض": "عشرت و خوشی با زنان و خیر و راحت از ایشان، و گرفتن مال؛ گم‌شده و گریخته زود به دست می‌آید؛ در سفر راحت می‌بیند؛ اما بیمار را بیم تلف است.", "عقله": "دلتنگی به خاطر زنی حامله، که به سلامت می‌زاید؛ بیمار زنده می‌ماند؛ سفر و همنشینی با زنان و دوستان نیک است؛ ازدواج نیک است؛ روز یکشنبه از احوال آگاه می‌شود.", "اجتماع": "پیوستن به زنان و زود رسیدن غایب و دلخوشی از عشرت؛ اما جنگ و خصومت بر سر مال میراث است؛ اگر سؤال از بزرگان باشد از ایشان خیر و راحت می‌بیند.", "فرح": "خیر و خوبی و گشایش کار و کسب و نیکویی عاقبت؛ گرفتن مال از زن، و جواهر و زینت زنان؛ محبت میان دوستان؛ سفر نیک است ولی در راه از دزد بپرهیزد.", "نصره الخارج": "نیکویی کارها و رسیدن خیر و راحت از بزرگان چون پادشاه و اهل دیوان؛ سفر نیک است؛ ازدواج و شرکت مبارک است؛ مال و کالا به دست می‌آید؛ روز یکشنبه یا آدینه از احوال آگاه می‌شود.", "عتبه الداخل": "سعادت و سلامتی و گشایش کارهای بسته؛ خواسته‌ای که از پادشاه دارد برآورده می‌شود؛ در سفر از ایشان نیکی و فایده می‌رسد؛ فروختن اسب بسیار نیک است و مقصود حاصل می‌شود.", "جماعت": "زیان مال و اندوه به سبب غلام و کنیز و چهارپایان، و از مردم بداصل و سخن‌چین و فریبکار؛ جنگ و خصومت و شکست لشکر و دست زدن به کارهای ناپسند.", "نقی الخد": "سفر و حرکتی که در آن غم و اندوه از سبب زنان یا غلام و کنیز یا غایبی می‌رسد؛ اگر سؤال از عشق باشد زود میسر می‌شود اما در آن رنج می‌بیند؛ در دعوی و مناظره کم پیروز است.", "قبض الخارج": "زیان مال و غم و اندوه و بستگی کار؛ به غایب آسیب رسیده؛ گریخته و گم‌شده به دست می‌آید؛ جدایی دوستان و نزاع میان زنان و کشته شدن دشمنان؛ اما سفر را نیک است.", "انکیس": "غم و اندوه و زیان مال و خصومت به سبب چیزهای گم‌شده، و تلف شدن چهارپایان و گریختن غلام و کنیز؛ اگر سؤال از بیمار یا حامله باشد دشوار است؛ روز شنبه از غایب خبر خوش می‌رسد.", "عتبه الخارج": "سفر و گرفتن مال؛ گم‌شده به دست می‌آید؛ اما جنگ و خصومت با دوستان و شریکان و زنان، و بدگویی مردم فرومایه و شنیدن سخن ناخوش و گلایه‌ی دوستان هست.", "قبض الداخل": "زیان مال و خصومت میان شریکان؛ اما شرکت و عشق و زن خواستن همه نیکوست؛ اگر سؤال از حاجت باشد بعضی حاصل می‌شود؛ غایب زود بازمی‌گردد؛ روز یکشنبه از احوال آگاه می‌شود.", "طریق": "سفر و حرکت و زیان مال و گریختن بندگان و خیانت زیردستان؛ جنگ و خصومت و طلب مال غایب؛ اگر سؤال از بیمار باشد جایش عوض می‌شود.", "حمره": "زیان مال و زیان چهارپایان؛ اگر سؤال از ازدواج باشد نیکوست؛ خصومت و خشم و تندی هست؛ اگر سؤال از غایب باشد از دشمنی که چون دوست نزدیک است غم رسیده است."}, "فرح": {"جماعت": "جمع شدن جماعتی بر کار خیر و صلاح و عیش و تماشا؛ اگر سؤال از فروختن چهارپا باشد خیر است؛ غایب مدتی می‌ماند؛ روز آدینه از ضمیر آگاه می‌شود.", "فرح": "سفر و حرکتی با فایده؛ جمع شدن برای عشرت؛ عشق زود میسر می‌شود؛ قوت دل و شادی و طرب و زادن فرزند؛ غایب زود می‌رسد و دشمن از میان می‌رود.", "انکیس": "ترس و غم و اندوه از پادشاه و یارانش به سبب تهمت؛ کار ناروا با زنان؛ بیمار را بیم است؛ روز شنبه از ضمیر آگاه می‌شود.", "نصره الخارج": "سفر و حرکت از جانب بزرگان؛ خرید و فروش نیک است و چهارپا به دست می‌آید؛ عزت و جمع شدن با دوستان؛ گم‌شده روز یکشنبه به دست می‌آید؛ اما جنگ و مناظره و خصومت هم هست.", "حمره": "نیکویی ازدواج و گرفتن مال و رهایی زن حامله و بهبود بیمار؛ اما جنگ و خصومت و جدایی میان دوستان؛ سفر ناپسند است؛ نفرین دشمن و ترس تا بیست و یک روز.", "عقله": "غم و اندوه و بستگی کارها و زیان مال و انواع ترس؛ بیمار تا پنجاه روز چون زندانی بدحال است؛ روز شنبه از احوال آگاه می‌شود؛ غایب با رنج و سختی بازمی‌آید.", "بیاض": "عیش و تماشا و عشرت، و رسیدن آنچه امید دارد؛ عروسی و ختنه‌سوران و ساختن بنا و گردش در تفرجگاه؛ اما زیان مال به سبب دزدی؛ روز دوشنبه از احوال آگاه می‌شود.", "طریق": "سفر و حرکت و گرفتن مال و گشایش کار و کسب و نیکویی عاقبت؛ اگر سؤال از بیمار باشد بیم است؛ غایب بازمی‌آید و با جماعت دوستان جمع می‌شود؛ روز دوشنبه از ضمیر آگاه می‌شود.", "نقی الخد": "دلتنگی به سبب مراد، اما میسر می‌شود؛ خرید و فروش و گرفتن مال غایب؛ گم‌شده به دست می‌آید؛ خریدن غلام و کنیز و گشایش کارها؛ روز دوشنبه آگاه می‌شود.", "اجتماع": "جمع شدن با غایب یا دوستی عزیز؛ اگر سؤال از گم‌شده و گریخته باشد دشوار به دست می‌آید؛ بیماری دراز می‌کشد؛ در سفر مکر و فریب است؛ باید تحمل کند.", "قبض الخارج": "سفری که در آن مال به دست می‌آید؛ روز آدینه از احوال آگاه می‌شود؛ گم‌شده به دست می‌آید؛ اما میان او و شریکان جنگ است؛ اگر سؤال از بیمار باشد بیم و خطر است.", "عتبه الداخل": "زیان و تلف مال در فسق و عشرت با زنان بدکار؛ اگر سؤال از بیمار یا زندانی باشد رها می‌شود؛ اما مال ازدست‌رفته دشوار به دست می‌آید؛ روز یکشنبه از ضمیر آگاه می‌شود.", "لحیان": "نیکویی عاقبت و گشایش کار و کسب و گرفتن مال و سال مبارک؛ اگر سؤال از غایب باشد به سلامت بازمی‌آید؛ کار به نظام است؛ نکاح مبارک است؛ جمع شدن با دوستان و یاران.", "قبض الداخل": "خیر و راحت و گشایش کارها و عیش و تماشا و دلخوشی از هر نوع؛ اگر سؤال از شغل و منصب باشد میسر می‌شود؛ هر حاجتی زود به دست می‌آید؛ روز یکشنبه از ضمیر آگاه می‌شود.", "عتبه الخارج": "گرفتن مال و سفر و حرکت و یافتن مراد، و انواع خیر و بشارت؛ چهارپا و غلام و کنیز و جامه‌ی زنانه به دست می‌آید؛ احوال سائل نیکوست.", "نصره الداخل": "زیان مال از سوی زنان و کنیزان و تلف شدن بندگان؛ اما بیمار بهبود می‌یابد؛ از سوی بزرگان و یاران قدیم خیر و راحت می‌رسد."}, "حمره": {"جماعت": "زیان و تلف مال و جنگ و خصومت و خون ریختن و آتش‌سوزی؛ اما اگر سؤال از سفر باشد در آن سفر خیر و راحت است.", "حمره": "جنگ و خصومت لشکرها و سفرهای نامبارک؛ گریخته و چهارپای رمیده دشوار به دست می‌آید؛ دعوی و مناظره پیش حاکمان؛ اما نکاح را نیک است.", "انکیس": "غم و اندوه بر سر گرفتن مال، و دعوی از سوی دیگران؛ اگر سؤال از گرفتن مال باشد ترس و سختی به حکم پادشاه است؛ روز شنبه از احوال آگاه می‌شود.", "قبض الداخل": "گرفتن مال و کالا از بهای چهارپا؛ اگر سؤال از بیمار باشد دراز می‌کشد؛ نکاح با زن بدنام و شرکت ناپسند؛ زندان و بند.", "نصره الخارج": "خیر و سلامت و خوبی و گشایش کار و نیکویی عاقبت؛ سفر مبارک است؛ گریخته و گم‌شده به دست می‌آید؛ آنچه امید دارد از طرف بزرگان می‌رسد و به همه‌ی مرادها می‌رسد.", "لحیان": "خیر و سعادت و نیکویی عاقبت و مبارکی روزگار؛ اگر سؤال از نکاح باشد مبارک است؛ گریخته و گم‌شده به دست می‌آید؛ کسب گشاده است؛ حاجتی که به دوستان و بزرگان دارد زود میسر می‌شود.", "نصره الداخل": "خیر و راحت و به دست آمدن مال گم‌شده و گشایش کارهای بسته و رسیدن به امید؛ خرید و فروش نیک است؛ زن خواستن و شرکت و غایب همه نیکوست.", "عتبه الداخل": "خیر و راحت و خوبی و گشایش کارها و کسب و رسیدن به امید از هر نوع؛ شرکت و عروسی و زن خواستن همه نیکوست.", "اجتماع": "جمع شدن با زنان و گرفتن مال و افزونی املاک و درجه؛ اگر سؤال از بیمار باشد بیم است؛ با غایب جمع می‌شود؛ در سفر نیکویی می‌بیند.", "بیاض": "خیر و سلامت و خوبی و گشایش کار و افزونی املاک؛ عیش و طرب با دوستان؛ غایب به سلامت می‌رسد و مال به دست می‌آید؛ شرکت و ازدواج نیکوست.", "طریق": "سفر و حرکت و جابه‌جا شدن بی‌اختیار؛ جنگ و دعوی؛ گم‌شده و گریخته دشوار به دست می‌آید؛ بیمار را بیم مرگ است؛ زن حامله زود فارغ می‌شود.", "نقی الخد": "غم و اندوه از سوی زنان و مردان و زیان مال در سفر؛ جنگ و خصومت؛ نکاح با زن بدنام؛ دل‌مشغولی به خاطر بیمار.", "قبض الخارج": "غم و اندوه و زیان مال و گریختن بندگان و تلف چهارپایان؛ جنگ و خصومت و جدایی میان دوستان.", "عتبه الخارج": "سفر و حرکت بی‌فایده و غم و اندوه و بستگی کار و کسب؛ اگر سؤال از غایب باشد کارش روا می‌شود؛ بیمار را بیم مرگ است؛ حاجتی که به دوستان دارد میسر می‌شود.", "فرح": "زن حامله یا دختر بکر؛ جنگ و خصومت و مناظره؛ بیماری که از آن بیم مرگ نیست؛ خرید و فروش چهارپا.", "عقله": "خیر و خوبی و گشایش کار و کسب و گرفتن مال؛ شرکت و زن خواستن نیک است؛ خرید غلام و کنیز؛ سال نیک است؛ گم‌شده به دست می‌آید؛ عیش و تماشا با دوستان نیکوست."}, "بیاض": {"بیاض": "سفر و حرکت دریا و خریدن باغ و بوستان؛ اگر سؤال از بیمار باشد بیم است؛ جمع شدن با زنان و عروسی و ختنه‌سوران؛ اگر سؤال از غایب باشد به زودی با دوستان می‌رسد.", "جماعت": "نامه و پیغام از سوی زنان و دوستان می‌رسد؛ گرفتن مال؛ خریدن کنیز و چهارپا و مروارید و نقره؛ گشایش کار و کسب.", "نصره الداخل": "افزونی چهارپا و پوشاک؛ گم‌شده به دست می‌آید؛ نامه و پیغام از غایب و دوستان می‌رسد؛ اگر سؤال از بیمار باشد رنج دراز است؛ از پادشاه بیم هست.", "انکیس": "غم و اندوه بر سر گرفتن مال؛ سفر نیکوست؛ از غایب و دوستان خبری شادی‌بخش می‌رسد؛ گشایش کار؛ اگر سؤال از پادشاه باشد روز دوشنبه به مراد می‌رسد.", "لحیان": "مال غایب از جانب دریا می‌رسد و با غایب جمع می‌شود؛ چهارپایی که به دست می‌آید زود تلف می‌شود؛ پرورش زیردستان و نکاح؛ با جماعت دوستان جمع می‌شود.", "قبض الخارج": "سفر و حرکت و جابه‌جا شدن؛ گریختن بندگان و تلف چهارپایان؛ اگر سؤال از بیمار باشد بیم است؛ اما غایب زود می‌آید و زن حامله پسر می‌زاید.", "اجتماع": "جمع شدن مال از میراث یا کالا؛ جنگ و خصومت و دعوی و مناظره؛ اگر سؤال از عیش باشد زود میسر می‌شود؛ روز سه‌شنبه به مراد می‌رسد.", "حمره": "سفر و حرکت و گفت‌وگو بر سر مال؛ نکاح با دختر بکر که در آن خیر و راحت است؛ گشایش کارها؛ روز چهارشنبه از احوال آگاه می‌شود.", "فرح": "خیر و خوبی و گشایش کار و کسب و نیکویی عاقبت؛ عیش و تماشا و عروسی و جمع شدن با زنان؛ خیر و راحت از دوستان؛ نکاح با فایده و سفری که عاقبتش پسندیده است.", "طریق": "نامه و خبر دوستان در سفری با فایده؛ اگر سؤال از ازدواج باشد میسر می‌شود؛ گم‌شده دشوار به دست می‌آید؛ گشایش کار و کسب و جمع کردن مال.", "عقله": "فساد و تباهی میان زنان و مردان؛ اگر سؤال از زن حامله باشد پسر می‌زاید؛ بیمار را بیم است؛ بستگی کار و کسب؛ اما خرید و فروش بهتر می‌شود.", "نقی الخد": "گرفتن مال و دل باختن به زنان بدنام؛ گریختن بندگان و زیردستان و گفت‌وگو میان دوستان؛ سفر به اختیار خود اوست؛ روز دوشنبه به مراد می‌رسد.", "نصره الخارج": "گشایش کار و کسب و نیکویی عاقبت و خیر و راحت از سوی بزرگان؛ نیکویی حال مسافر؛ پیروزی بر دوستان و دشمنان؛ هر حاجتی بخواهد زود میسر می‌شود.", "عتبه الخارج": "زیان مال، اما خیر و راحت از سوی بزرگان؛ دعوی و مناظره پیش پادشاه؛ پیوستن به غایب؛ این مثلثه بعضی نیک است و بعضی نه، بسته به شواهد رمل.", "قبض الداخل": "خیر و خوبی و گشایش کار و گرفتن مال و معامله؛ عیش و تماشا با دوستان؛ سفر و تجارت و زن خواستن و شرکت نیک است.", "عتبه الداخل": "گرفتن مال و نیکویی عاقبت و افزونی چهارپایان؛ رسیدن غایب و خوشدلی از سوی پادشاه؛ یافتن مراد پس از مدتی؛ جمع شدن با زنان."}, "عتبه الداخل": {"جماعت": "گرفتن مال و جمع شدن با زنان؛ عزت و بلندی و معامله‌ی با فایده و خرید و فروش؛ ازدواج و شرکت نیک است؛ پیوستن به دوستان عزیز و یاران موافق.", "عتبه الداخل": "سفر و حرکت و خرید و فروش؛ جمع شدن لشکرها؛ گرفتن مال‌ها و افزونی املاک؛ دل به عشرت و آسایش با دوستان عزیز و یاران هم‌دل خوش است.", "اجتماع": "سفر و حرکت و جمع شدن با غایب؛ در نکاح و شرکت پرهیز بهتر است؛ جنگ و خصومت و دعوی و مناظره و زیان مال، و غم و اندوه از زندان یا بیماری.", "انکیس": "زیان مال و جاه و حرمت و افتادن از مرتبه؛ بستگی کار و کسب و غم و اندوه از مردم بداصل؛ اما خریدن غلام و کنیز و چهارپا نیک است؛ از گم‌شده بعضی به دست می‌آید.", "لحیان": "سعادت و سلامت و گشایش کارها؛ دعوی و مناظره بر سر چیزهای گم‌شده؛ هرچه امید دارد می‌رسد؛ جمع شدن با زنان و دوستان و به دست آوردن مال و تجارت.", "طریق": "سفر و حرکت و جابه‌جا شدن؛ اگر سؤال از زیان یا دزدی باشد به دست می‌آید؛ زندانی و زن حامله زود رها می‌شوند؛ غایب با دوستان عزیز می‌رسد.", "حمره": "سفر و حرکت و خریدن پارچه و جامه‌ی زنانه؛ نکاح با دختر بکر، و آبستن پسر می‌زاید؛ غایب زود می‌آید؛ زر به دست می‌آید؛ از بعضی بزرگان و اهل دولت بیم هست.", "نصره الداخل": "زیان مال و گریختن زیردستان؛ اما جمع شدن با زنان و عشرت و تماشا نیکوست؛ غایب زود می‌آید؛ سفر؛ دیگران قصد دشمنی دارند؛ بیمار را بیم است.", "قبض الداخل": "خیر و خوبی و گشایش کارها از هر نوع؛ سفر نیکوست؛ معامله و شرکت و زن خواستن همه مبارک است؛ اما بیمار را از بیماری‌اش بیم است.", "بیاض": "روزی حلال و گرفتن مال و نیکویی کار و کسب و سلامت تن؛ عیش و تماشا و عشق؛ مقصود حاصل می‌شود و خبر و نامه می‌رسد؛ به غایب می‌پیوندد؛ طالع نیک و مبارک است.", "نقی الخد": "غم و اندوه از سوی زنان؛ زیان مال، اما بعضی به دست می‌آید؛ اگر سؤال از نکاح و شرکت باشد صاحب ضمیر از سوی بزرگان و اهل دولت یاری می‌بیند.", "نصره الخارج": "سفر و حرکت و گشایش کار و کسب و رسیدن به مقصود از جانب معشوق؛ اما بیمار و زندانی را بد و دشوار است؛ اگر سؤال از غایب باشد به سلامت است و زود می‌رسد.", "عقله": "غم و اندوه و بستگی کارها و دلتنگی؛ دعوی و مناظره؛ اگر سؤال از غایب باشد کارش پریشان است؛ خریدن کنیز و چهارپا؛ زن خواستن میانه است.", "عتبه الخارج": "سفر و حرکت و جابه‌جا شدن؛ زندانی رها می‌شود اما بیماری دراز می‌کشد؛ جمع شدن با غایب و ایمن شدن از ترس.", "فرح": "سلامت تن و گشایش کار و کسب و دلخوشی از جانب برادران؛ زیان مال، اما بعضی به دست می‌آید؛ اگر سؤال از بیمار باشد زود از بیماری و ترس رها می‌شود.", "قبض الخارج": "سفر و حرکت و غم و اندوه و نامرادی از جانب دوستان؛ اگر سؤال از بیمار باشد بیم است؛ زن خواستن نیکوست؛ شب یکشنبه احوال معلوم می‌شود؛ خصومت و غم هم هست."}, "عتبه الخارج": {"جماعت": "زیان مال و غم و اندوه و بستگی کار و کسب؛ جنگ و خصومت و شکست لشکر و کم شدن چهارپا؛ رنج بیمار دراز می‌کشد.", "عتبه الخارج": "سفر و حرکت و جابه‌جا شدن؛ رسیدن چیزهای ناخوش؛ سوختن پوشاک و گریختن زیردستان؛ اما از ترس و خطر ایمن است.", "انکیس": "غم و اندوه و زیان مال و زیان چهارپا؛ دزدی و بستگی و پریشانی از سوی زنان و بندگان؛ روز دوشنبه از ضمیر آگاه می‌شود.", "طریق": "سفر و حرکت و زیان مال و زیان از چهارپا؛ جنگ و خصومت و جدایی میان دوستان و برادران؛ این مثلثه در همه‌ی احوال ناپسند است؛ دشمنی که نزدیک است آشکار می‌شود.", "لحیان": "حرکت و سفر و گرفتن مال و گشایش کار و کسب؛ زن خواستن مبارک است؛ دعوی و مناظره پیش بزرگان؛ رفتن به دنبال حاجت؛ گریختن بندگان؛ فروش چهارپا.", "اجتماع": "جمع شدن با غایب؛ همنشینی با اهل علم و ادب و آموختن؛ استواری کارها و به دست آوردن مال؛ اما همنشینی با زنان بدکار بد است؛ زیردستان در مال خیانت می‌کنند.", "قبض الخارج": "سفر ناپسند و زیان مال و تلف چهارپا و گریختن زیردستان؛ اگر سؤال از بیمار باشد بیم است؛ ناسازگاری میان دوستان و برادران و جنگ و خون‌ریزی میان شریکان.", "حمره": "جنگ و خصومت و شر و غم و اندوه و خون‌ریزی؛ جدایی میان دوستان و زنان و شریکان؛ بستگی کارها و دل‌مشغولی و ترس از گریخته و غایب.", "نصره الخارج": "سفر و حرکت و جابه‌جا شدن، و خیر و راحت از سوی پادشاه و یارانش؛ میراث و گرفتن مال و گشایش کار و کسب؛ روز یکشنبه به مراد می‌رسد.", "بیاض": "خیر و سعادت و گشایش کار و کسب؛ گم‌شده به دست می‌آید؛ اگر سؤال از زنان باشد شاد می‌شود؛ بیمار یا زندانی پس از سختی کاملاً رها می‌شود؛ همه‌ی احوال نیکوست.", "فرح": "افزونی چهارپا و غلام و کنیز؛ همنشینی با دوستان و دست زدن به کار بزرگان؛ گفت‌وگو از سوی زنان؛ اما سفر مبارک است.", "نصره الداخل": "عیش و تماشا و عشرت با معشوق و گشایش کار و کسب؛ آمدن غایب و سفر مبارک؛ اما دعوی و مناظره بر سر قرض و خصومت با شریکان هست.", "نقی الخد": "به دست آوردن مال و میراث؛ غم و اندوه از سوی زنان و پریشانی به خاطر بیمار یا زندانی یا گریخته؛ سفر ناپسند است؛ دشمنی که نزدیک است آشکار می‌شود.", "قبض الداخل": "همنشینی با یاران خوش و یافتن مراد و لذت از ایشان؛ اما خواسته دشوار به دست می‌آید؛ سفر بد است ولی غایب به سلامت است؛ با شریکان خصومت است؛ شب یکشنبه آگاه می‌شود.", "عقله": "گرفتن مال غایب از راه فروش چهارپا؛ شرکت و زن خواستن نیک است؛ اگر سؤال از بیمار یا زن حامله باشد در ترس و بیم است؛ سفر دریا.", "عتبه الداخل": "دلخوشی از زنان و روزی حلال؛ اگر سؤال از شغل باشد میسر می‌شود و کار و کسب گشاده است؛ غایب به سلامت است؛ اما سفر ناپسند است و مکری در پیش است."}, "نصره الخارج": {"جماعت": "سلامت و سعادت و گشایش کارها و نیکویی احوال؛ خیر و راحت از پادشاه و یارانش؛ دعوی و مناظره؛ چهارپایی به دست می‌آید؛ جمعی بسیار به سبب مال پادشاه گرد می‌آیند.", "نصره الخارج": "سفر و حرکت و بزرگی و مرتبه یافتن و گرفتن مال از پادشاه؛ خرید و فروش نیکوست؛ زر و سیم و جواهر به دست می‌آید.", "قبض الخارج": "سفر و حرکت با جماعت بزرگان و فایده یافتن؛ گفت‌وگوی یاران بر سر گرفتن مال؛ زن خواستن ناپسند است؛ مال زنان و شریکان به سائل می‌رسد.", "اجتماع": "سعادت و گشایش کار و خیر و راحت و کسب از طرف بزرگان؛ زن خواستن و عشق؛ مال ازدست‌رفته دشوار به دست می‌آید؛ بیمار بهبود می‌یابد؛ روز چهارشنبه به مراد می‌رسد.", "عقله": "طلب کردن چهارپایی که به دست می‌آید؛ شادی از سوی پادشاه یا امیری؛ دعوی میان دو کس بر سر همین چیز؛ خریدن چهارپا و غلام و کنیز و گرفتن مال.", "قبض الداخل": "خیر و سعادت و خبر و نامه از غایب؛ آموختن علم و ادب؛ سفر و حرکت از جانب پادشاه و حاجت خواستن؛ زن خواستن نیک است؛ بیمار بهبود می‌یابد؛ روز یکشنبه آگاه می‌شود.", "فرح": "بیرون آمدن از غم و اندوه؛ اما بستگی کار و زیان مال و ضایع شدن حاجت‌ها هم هست؛ ترس از سوی پادشاه، که پس از روز آدینه ایمن می‌شود.", "انکیس": "سختی که از سوی بزرگان می‌رسد، اما مراد از ایشان یافته می‌شود؛ روز دوشنبه به مراد می‌رسد؛ از دوستان به امید می‌رسد؛ اگر سؤال از دوست غایب باشد به مراد می‌رسد.", "لحیان": "سلامت و یافتن مراد دل پس از سختی و ترس؛ گشایش کار و کسب و خیر و راحت و مرتبه از سوی بزرگان؛ سفر نیک است؛ جمع شدن با غایب.", "حمره": "یافتن مقصود و مراد از پادشاه و یارانش و ایمن شدن از غم‌ها؛ آنچه امید دارد می‌رسد؛ گم‌شده و گریخته پیدا می‌شود؛ نکاح مبارک است؛ سفر و دعوی پیش حاکمان.", "عتبه الداخل": "عیش و تماشا و شادی و گشایش کار و کسب؛ خبر و نامه از غایب؛ گرفتن مال و رسیدن به مقصود و کام دل از هر نوع.", "نقی الخد": "نیکویی حال دوستان و رسیدن به معشوق؛ گرفتن مال و پیروزی بر دشمن؛ زن حامله پسر می‌زاید؛ اما بیمار را بیم است؛ پس از یازده روز دشمنی آشکار می‌شود.", "عتبه الخارج": "سعادت و مرتبه‌ی بزرگی و گشایش کار و کسب و پیروزی و کام دل؛ حرکت و گرفتن مال؛ گم‌شده به دست می‌آید؛ بیمار را بیم است؛ روز پنجشنبه به مراد می‌رسد.", "بیاض": "نیکویی جاه و مرتبه یافتن از پادشاه؛ از ترس ایمن است و به امیدی که دارد می‌رسد؛ غایب و زن خواستن مبارک است؛ اما چهارپایان زیان می‌بینند.", "طریق": "مقصود و مرادی که از سوی بزرگان یا پادشاه می‌رسد؛ سفری مبارک از جانب ایشان؛ سلامت غایب و گشایش کار و کسب؛ زن حامله سختی می‌کشد.", "نصره الداخل": "سفر و حرکت نزد پادشاه؛ خیر و خوبی و فایده از چهارپایان بزرگ؛ عیش و طرب و رسیدن به مقصود از دوستان؛ نکاح و شرکت نیکوست؛ اما گم‌شده و دزدیده دشوار به دست می‌آید."}, "طریق": {"لحیان": "عزت و مرتبه و گشایش کار و کسب و راحت از طرف بزرگان؛ زندانی و حامله رها می‌شوند؛ سفر و حرکت به خاطر مال؛ اگر سؤال از پادشاه باشد راحت می‌یابد.", "عتبه الداخل": "سلامت تن و گشایش کارها و به دست آوردن مال از سوی زنان؛ خرید و فروش نیک است؛ اما لحیان اگرچه سعد است این‌جا جای نحس نشسته؛ زیان هم هست.", "انکیس": "شر و فتنه و زیان چهارپا و افتادن از مرتبه و بستگی در همه‌ی کارها؛ غم و اندوه به خاطر بیمار و کسی که به او بسته است.", "عتبه الخارج": "دزدی و تلف و زیان مال و غم و اندوه و بستگی کسب؛ افتادن از چهارپا و بدحالی مسافر؛ جنگ و خصومت؛ سفر نامبارک است؛ زیردستان بدحال‌اند.", "قبض الخارج": "سفر و آگاه شدن از احوال؛ روز دوشنبه آگاه می‌شود؛ گلایه‌ی دوستان؛ خیر و سعادت و گرفتن مال غایب؛ اگر سؤال از ازدواج باشد جنگ و جدایی دوستان است.", "قبض الداخل": "زیان مال و انواع غم و اندوه و بستگی کارها؛ سفر بد است؛ اگر سؤال از غایب باشد دوستان زود به هم می‌رسند؛ نکاح نیک است و زندانی رها می‌شود.", "نصره الداخل": "خیر و خوبی و سلامت تن و رسیدن مسافر به سلامت؛ حاصل شدن مقصود و دلخوشی از دوستان و گشایش کار و کسب؛ اما تلف مال از سوی زنان و جدایی میان زن و شوهر.", "نصره الخارج": "سفر و حرکت و خیر و راحت از سوی پادشاه؛ ازدواج مبارک است؛ زن حامله پسر می‌زاید؛ دلخوشی از دوستان و برادران؛ چهارپایی به دست می‌آید.", "نقی الخد": "مردم نادرست چون راهزن و دزد، و زیان مال و افتادن از جاه و مرتبه؛ مانع سفر؛ جنگ و خصومت و دعوی بی‌سبب؛ اگر سؤال از غایب باشد بد است.", "حمره": "کار حرام و خون‌ریزی؛ زیان مال زنان و گریختن بندگان؛ اگر سؤال از سفر باشد هیچ خیری در آن نیست؛ دشمنی از نزدیکان آشکار می‌شود.", "جماعت": "جماعتی غایب، و بیماری و مناظره؛ رسیدن غایب و سفر از راه دریا؛ زیان چهارپا؛ جنگ و خصومت و زیان از سوی زنان.", "طریق": "گشایش کار و کسب در بازارها و آمیختن با مردم عامه؛ جدایی میان دوستان؛ راحت از طرف بزرگان.", "فرح": "خیر و خوبی و گشایش کار و کسب و گرفتن مال و ایمنی؛ سفری با خیر؛ رسیدن به مقصود و کام دل از دوستان؛ نیکویی احوال فرزند.", "بیاض": "خیر و راحت از زنان و دوستان و روزی حلال؛ شرکت و ازدواج مبارک است؛ زندانی رها می‌شود؛ غایب می‌رسد اما در راه غمی دیده است.", "عقله": "دلتنگی؛ بیمار یا زن حامله یا زندانی؛ چیزهای میان‌تهی چون صندوق و تابوت؛ بیمار را بیم است؛ خریدن چهارپا با فایده است و مال به دست می‌آید.", "اجتماع": "جمع شدن با زنان و همنشینی، و رسیدن غایب یا دوستی عزیز؛ جنگ و خصومت بر سر گرفتن مال؛ سفر ناپسند است؛ روز چهارشنبه بر ضمیر آگاه می‌شود."}, "جماعت": {"جماعت": "جماعت‌ها چون لشکرها و قوم‌ها و درختستان‌ها؛ گرد آمدن برای سوگ یا شادی؛ جمع شدن با دوستان و عشرت.", "لحیان": "گشایش کارها و راحت از سوی بزرگان؛ جای مسجد و خانقاه و مجلس شرع و جماعت اهل صلاح؛ دلالت بر جواهر و زر و سیم.", "انکیس": "غم و اندوه و زیان چهارپا و مال؛ خبر دزد می‌رسد؛ بستگی کار و کسب؛ خصومت با جماعت طراران و مفسدان؛ بند و زندان و خیانت در میان است.", "اجتماع": "پیوند دو کس که در یک بستر باشند؛ اگر سؤال از بیمار باشد بیم هلاکت است؛ همنشینی با جماعت دوستان و یاران.", "نصره الخارج": "خیر و راحت از طرف بزرگان و یافتن مراد از پادشاه؛ سفر با بندگان؛ دو پادشاه که میانشان خصومت است، اما عاقبت کار به صلاح و سعادت می‌انجامد.", "نصره الداخل": "خریدن چهارپا، اما اندکی ترسناک است؛ سفر و حرکت و خیر و راحت از طرف بزرگان؛ جمع شدن با دوستان و عشرت با غایب.", "بیاض": "خیر و خوبی و آبادانی املاک و روزی حلال؛ عیش و طرب صاحب طالع با زنان؛ سفر دریا با خیر؛ رسیدن خبر و پیغام از دوستان و یاران.", "حمره": "غم و اندوه و جنگ و خصومت و قتل و راهزنی و آتش‌سوزی و جمع شدن برای سوگ؛ اما سفر در آن خیر دارد.", "نقی الخد": "مراد سائل از سوی مردان و زنان بدکار است که در آن خیری نیست؛ جنگ‌ها و فتنه‌ها میان ایشان؛ راهزن و دزد.", "فرح": "شادی و خیر و راحت؛ اما اگر بسیار تکرار شده باشد دلیل جنگ و فتنه و مردم بداصل و شرور و فتنه‌جوست.", "عتبه الداخل": "گشایش کارها و نیکویی عاقبت و جمع شدن با زنان؛ پرچم پادشاه؛ مشغول شدن به عشق و عیش و خرید و فروش.", "طریق": "جابه‌جایی و حرکت و سفر و رسیدن غایب؛ دعوی و مناظره‌ی شگفت؛ زنان سالخورده.", "عتبه الخارج": "سفرهای نامبارک و غم و اندوه و زیان مال و جنگ و خصومت و شکست لشکر و ویرانی املاک؛ مگر سفر زیارت که مبارک و میمون است.", "عقله": "جمع شدن زنان بر سر بیمار؛ روزی که می‌رسد؛ نکاح دختر بکر؛ حاجت‌هایی که از سوی پادشاه و بزرگان و اشراف برآورده می‌شود.", "قبض الخارج": "گرفتن مال و نکاح مبارک و خیر و سعادتی که در همان ماه می‌رسد؛ اگر سؤال از بیمار باشد دشوار است اما عاقبت به سلامت است؛ اگر بسیار تکرار شده باشد خیری در آن نیست.", "قبض الداخل": "جنگ و خصومت و زیان مال؛ اما حامله و زندانی را نیکوست؛ در سفر یاران بسیار همراه‌اند."}, "قبض الداخل": {"قبض الخارج": "گرفتن مال و کالا چون بهای چهارپا و غلام و کنیز؛ گشایش کار و کسب و آموختن علم؛ اما کار غایب بسته است؛ اگر سؤال از بیمار باشد بیم است؛ در سفر پس از دو روز خیر است.", "طریق": "سفر و حرکت و زیان مال و گریختن بندگان؛ اما سلامت تن و رسیدن نامه و خبر از غایب و دوستان؛ دعوی و مناظره و خصومت با زنان و شریکان؛ از ترس ایمن می‌شود.", "جماعت": "روزی حلال از نوشتن و کار؛ خریدن چهارپا و رسیدن خیر و فایده و گرفتن مال و جمع شدن با دوستان؛ شرکت و ازدواج با خیر و فایده است؛ روز چهارشنبه آگاه می‌شود.", "قبض الداخل": "سفر و حرکت و فایده و راحت از خریدن چهارپا؛ شرکت و معامله و ازدواج نیک است؛ مالی از راه شغل به دست می‌آید؛ روز یکشنبه از ضمیر آگاه می‌شود.", "نصره الداخل": "شرکت و زن خواستن و رسیدن نامه و خیر و راحت از زنان؛ گشایش کار و کسب و عشق؛ غایب به سلامت است و خبرش می‌رسد؛ شادی و عروسی پس از چهل و پنج روز.", "اجتماع": "جمعیت و همراهی با پادشاه؛ سفر مبارک است؛ زن خواستن و شرکت؛ چهارپایی به دست می‌آید؛ نامه می‌رسد؛ بیمار را بیم است.", "نصره الخارج": "نیکویی عاقبت کار و خیر و راحت از مردم بزرگ و برآمدن حاجت؛ گرفتن مال و گشایش کار و کسب؛ کیسه و باری بسته به دست می‌آید؛ پیوستن به غایب.", "عقله": "خیر و راحت از طرف بزرگان و امید از پادشاه و دوستی با ایشان؛ رسیدن به مقصود از هر نوع و کام دل؛ زن خواستن و شرکت و خریدن چهارپا نیکوست.", "بیاض": "عزت و رفعت جاه به یاری زیردستان؛ یافتن مراد از سوی زنان و دوستان؛ گرفتن مال و سود از پادشاه؛ آمدن غایب و رسیدن نامه؛ سفر مبارک است.", "عتبه الداخل": "گرفتن مال از پادشاه و ولایت، و چهارپا و غلام و کنیز؛ عیش و تماشا با دوست و پیروزی؛ گشایش کار و کسب؛ سفر مبارک؛ جمع شدن با زنان و حضور قاضی.", "حمره": "بستگی کارها و غم و اندوه و تلف چهارپا؛ زن حامله فارغ می‌شود؛ نکاح دختر بکر؛ سفر غایب ناپسند است؛ جنگ میان دوستان؛ روز سه‌شنبه آگاه می‌شود.", "انکیس": "استواری کارها و عزت و مرتبه از بزرگان؛ اما زن حامله و بیمار و زندانی را بد است؛ جنگ میان دوستان؛ روز شنبه آگاه می‌شود.", "لحیان": "سفر و حرکت و خیر و راحت از خرید و فروش و معامله و نیکویی کار و کسب؛ رهایی از همه‌ی غم‌ها و شادی از سوی بزرگان؛ اگر سؤال از غایب باشد به خیر است و با دوستان جمع می‌شود.", "فرح": "گشایش کارها و نیکویی تجارت و خریدن چهارپا و افزونی معاش و خوشدلی از جانب زنان؛ گم‌شده دشوار به دست می‌آید اما عاقبت نیکوست و از آنچه می‌ترسد ایمن می‌شود.", "نقی الخد": "زیان مال و دلتنگی و ترس، اما عاقبت به خیر است؛ امیدی که به دوستان دارد دشوار به دست می‌آید؛ کارهای ناروا زود میسر می‌شود.", "عتبه الخارج": "سفر و حرکت و غم و اندوه و زیان مال و دلتنگی؛ چهارپایی به دست می‌آید؛ از جانب پادشاه توجهی می‌رسد؛ اما در بیشتر کارها این صورت نحس است و غم و جنگ می‌آورد."}, "قبض الخارج": {"جماعت": "زیان مالی که هرگز به دست نمی‌آید؛ اما عیش و تماشا با معشوق و فارغ شدن زن حامله و بهبود بیمار؛ در سفر راحت است؛ شرکت و ازدواج نیکوست.", "قبض الخارج": "سفر و حرکت و زیان مال، اما بعضی به دست می‌آید؛ تلف کار و بیم از شریکان و خصومت و داوری و جدایی دوستان؛ با این همه گشایش کارها و شادی هم هست.", "طریق": "سفر و گفت‌وگو با شریکان بر سر مال، اما به دست می‌آید؛ بیمار پس از ترس کاملاً بهبود می‌یابد؛ گشایش کار و کسب؛ اگر سؤال از غایب باشد دیر می‌آید؛ سلامت تن.", "قبض الداخل": "گرفتن مال و نیکویی کار و کسب و سلامت تن؛ عیش و طرب با زنان و شریکان؛ کار به نظام است؛ بیمار پس از رنج و سردرد راحت می‌شود.", "فرح": "فروش چیزهای گوناگون با سود؛ آنچه امید دارد می‌رسد؛ گم‌شده به دست می‌آید؛ گشایش کارها و خیر و سفر و راحت از طرف بزرگان؛ روز آدینه آگاه می‌شود.", "عتبه الداخل": "خریدن زمین و مشغول شدن به ساختن بنا؛ چهارپایی به دست می‌آید؛ آموختن علم و ادب و رسیدن به مراد دوستان؛ ازدست‌رفته بازیافته می‌شود؛ بیمار بهبود و زندانی رهایی می‌یابد.", "نصره الخارج": "سفر و حرکت برای جاه؛ گم شدن چند چیز میان دوستان؛ اگر سؤال از غایب باشد زود می‌رسد؛ بیمار را بیم است؛ بر دشمنان پیروز می‌شود.", "اجتماع": "زیان مال و انواع ترس از بزرگان و گریختن زیردستان؛ اگر سؤال از غایب باشد با دوستان جمع می‌شود؛ عیش و تماشا و گفت‌وگو بر سر مال؛ روز چهارشنبه آگاه می‌شود.", "بیاض": "سعادت و گشایش کار و پیروزی بر دشمن و یافتن مراد دل از هر نوع؛ بیمار بهبود می‌یابد؛ غایب با دوستی زود می‌رسد؛ ساختن بنا و آبادانی.", "لحیان": "سفر و حرکت و گشایش کار و جمعیت؛ بیمار و زندانی و حامله رها می‌شوند؛ رهایی از همه‌ی غم‌ها؛ خریدن چهارپا و پارچه با سود؛ غایب به سلامت می‌رسد و گم‌شده بازمی‌آید.", "حمره": "تلف مال و ترس از تهمت و غم و زیان چهارپا؛ خیانت و گلایه‌ی دوستان و خصومت شریکان؛ اما عاقبت به خیر است؛ سفر باطل است.", "عتبه الخارج": "بدحالی و سرگردانی مسافر در سفر و باطل شدن کارها؛ فساد با دوستان؛ غم و اندوه و افتادن از جاه و بستگی کارها؛ کار غایب بی‌نظام است؛ اما بیمار راحت می‌یابد.", "نصره الداخل": "خیر و راحت از زنان و دوستان؛ فروش چهارپا؛ نیکویی کار و کسب و شرکت؛ آنچه امید دارد می‌رسد؛ پیغام از غایب و دوستان؛ سفر پسندیده است؛ این صورت سعد است.", "عقله": "زن آبستن و افزونی چهارپا؛ بیمار بهبود می‌یابد؛ اختلاف با دوستان بر سر مال؛ سفر دریا مبارک است؛ شرکت و معامله و زن خواستن نیکوست؛ روز پنجشنبه آگاه می‌شود.", "نقی الخد": "غم و اندوه و افتادن از مرتبه و زیان مال و بستگی کار؛ جنگ و خصومت با مردم بداصل و از سوی زنان و غلام و کنیز؛ سفر ناپسند است؛ میان دوستان جدایی می‌افتد.", "انکیس": "زیان مال و چهارپا و غم و اندوه و بستگی کار؛ خیانت زیردستان و خصومت؛ اگر سؤال از بیمار یا حامله باشد دشوار است؛ از زیردستان زیان مالی می‌رسد."}, "اجتماع": {"نقی الخد": "آشتی دادن میان مردم و نزدیکی با بزرگان؛ عیش و طرب؛ خرید و فروش؛ رهایی بیمار و گشایش کار و کسب؛ اما سفری که در پیش است ناپسند است.", "فرح": "سلامت و سعادت تن و پیوستن به زنان و دوستان؛ سفر و حرکت برای چهارپایی که به دست می‌آید؛ اما خصومت و دعوی با شریکان و زنان هست.", "عتبه الداخل": "خرید و فروش و شرکت و ازدواج نیکوست؛ چیزهای گم‌شده به دست می‌آید؛ اگر سؤال از غایب باشد با دوستان یا خویشان جمع می‌شود.", "انکیس": "رفتن نزد پادشاه و بزرگان و یافتن خیر و راحت از ایشان؛ گم‌شده به دست می‌آید؛ روز شنبه از ضمیر آگاه می‌شود؛ چهارپایان به دست می‌آیند.", "لحیان": "نزدیکی به بزرگان و دل‌مشغولی برای مال و طلب مرتبه؛ دعوی و مناظره و ترس و بیم برای شغل؛ بیمار یا زندانی رها می‌شود.", "عتبه الخارج": "سفر و تلف مال غایب و زیردستان؛ پیوستن به غایب؛ کام دل از طرف زنان؛ زیان چهارپا؛ آنچه تلف شده دشوار به دست می‌آید؛ روز پنجشنبه آگاه می‌شود.", "حمره": "سفر و رسیدن غایب و خریدن چهارپا و چیزهای سفید از هر نوع؛ رسیدن نامه و پیغام؛ کار و کسب نزد بزرگان؛ عشرت و ازدواج نیکوست؛ روز دوشنبه به مراد می‌رسد.", "بیاض": "خونی که از تن می‌رود و هرچه به سرخی می‌گراید؛ زن حامله و زیان مال؛ نامه و پیغام دوستان غایب می‌رسد؛ از طرف بزرگان خیر و راحت؛ دشمن قصد مال دارد.", "جماعت": "جمع شدن مال و دوستان و عشرت با یکدیگر؛ گشایش کار در بازار و معامله؛ خریدن چهارپا و غلام و کنیز؛ به دست آوردن مال و نیکویی شرکت و زن خواستن؛ روز چهارشنبه آگاه می‌شود.", "اجتماع": "جمع شدن با دوستان و زنان؛ رسیدن غایب و نیکویی کار و معامله و رسیدن به کام دل؛ دعوی از سوی زنان؛ اگر سؤال از سفر باشد آن را رها می‌کند؛ روز چهارشنبه معلوم می‌شود.", "طریق": "سفر و شرکتی با خیر و سلامت تن و جمع شدن دوستان؛ آمدن غایب و پیغام عشق؛ پیروزی بر دشمن؛ گرفتن مال و گشایش کار و رهایی زندانی؛ اما بیمار را دشوار است.", "عقله": "زن حامله و بیماری چهارپایان و بیماری که از آن بیم مرگ است؛ زیان مال و گریختن زیردستان؛ روز شنبه یا دوشنبه آگاه می‌شود.", "نصره الداخل": "سلامت تن و نیکویی احوال و گرفتن مال و چهارپا و غلام و کنیز؛ دلتنگی از سوی دوستان و دشمنی نزدیک؛ رسیدن غایب و به دست آمدن کالا و سود.", "قبض الداخل": "سفر و حرکت برای خریدن چهارپا و غلام و کنیز؛ جمع شدن با دوستان و زنان؛ روز پنجشنبه آگاه می‌شود؛ شرکت؛ زن خواستن مبارک است.", "قبض الخارج": "سفر و حرکت و ترس و بیم از طرف پادشاه؛ آنچه طلب می‌کند دشوار به دست می‌آید؛ گفت‌وگو و ناسازگاری دوستان؛ از زنان خیری نیست؛ چهارپایی به دست می‌آید.", "نصره الخارج": "بزرگی و مرتبه از طرف پادشاه؛ گم‌شده و گریخته به دست می‌آید؛ گشایش کار و کسب و پیروزی؛ اما سفر و حرکت بد است."}, "عقله": {"اجتماع": "کام دل یافتن از زنان و شریکان؛ فروش چهارپا با سود؛ اگر سؤال از غایب باشد دلتنگی دیده؛ سفر ناپسند است؛ اما گشایش کار هست؛ بیمار را بیم است؛ زنی برای طلب چیزی دشمنی می‌کند.", "طریق": "سفر و حرکت به مبارکی و خیر و راحت از سوی زنان یا مردی؛ گفت‌وگو میان دوستان و نزدیکان؛ طلب شغل و منصب از پادشاه.", "عتبه الداخل": "زیان مال و غم و اندوه؛ اما از زنان خیر و راحت می‌رسد و حال شریکان نیکوست؛ بیمار یا زندانی رها می‌شود؛ روز آدینه آگاه می‌شود.", "عتبه الخارج": "باطل شدن سفر؛ اما گرفتن مال و گشایش کار و کسب و آموختن علم و ادب؛ غایب به سلامت می‌رسد؛ دعوی هست؛ روز شنبه یا آدینه از ضمیر آگاه می‌شود.", "عقله": "سفر و حرکت به خاطر چهارپا و ملک و زمین و ساختن بنا؛ فرستادن نامه و پیغام؛ اما سفر ناپسند است؛ نکاح و شرکت پسندیده است.", "جماعت": "زن حامله و بیماری و بستر؛ فروش چهارپا و غلام و کنیز؛ راحت از زنان؛ شرکت و زن خواستن و دعوی و مناظره؛ این مثلثه بر همه‌ی نیکی‌ها و بارهای بسته دلالت دارد.", "قبض الداخل": "سفر و حرکت به سعادت و بزرگی و مرتبه‌ی بلند؛ دعوی پیش بزرگان بر سر املاک و سختی کشیدن از آن، اما آخر کار آسان می‌شود؛ زن خواستن نیکوست.", "نصره الخارج": "خیر و سعادت و گرفتن مال از هر نوع؛ زن خواستن مبارک است؛ سفر و حرکت از سوی بزرگان و گشایش کارها از ایشان؛ این صورت بر چیزهای گران‌بها دلالت دارد.", "نصره الداخل": "فروختن چیزهای خاص؛ جابه‌جا شدن به سبب مال و چهارپا؛ پریشانی از سوی فرزندان؛ غایب می‌رسد؛ اما اگر سؤال از نکاح باشد بد است و زود به جدایی می‌کشد.", "قبض الخارج": "سفر و حرکت و گرفتن مال از بهای چهارپا؛ خصومت با دوستان و نزدیکان؛ غایب می‌رسد؛ زیان از زیردستان و تلف چهارپا.", "لحیان": "کارهای بزرگ و بزرگی از سوی زنان؛ خرید و فروش چهارپا؛ گفت‌وگو بر سر گم شدن چیزی؛ و نیز کارهای بسته.", "انکیس": "غم و اندوه به خاطر غایب؛ اما نکاح با کنیز نیک است؛ شرکت و دعوی پسندیده است.", "نقی الخد": "طلب روزی حلال و خیر و راحت از زنان؛ ساختن بنا و دلخوشی از دوستان؛ به آنچه می‌خواهد می‌رسد؛ اگر سؤال از بیمار باشد بیم و غم است؛ غایب به سلامت زود می‌آید.", "بیاض": "راحت از زنان؛ جنگ و خصومت و دعوی و مناظره، اما عاقبت کارها به خیر است؛ عیش و طرب با جماعت دوستان؛ اما زنی به سبب طلب چیزی دشمنی می‌کند.", "حمره": "دیدن دختر بکر یا مال زنان که به دست می‌آید؛ گشایش کار و کسب و زن خواستن و خیر و راحت از سفر؛ به آنچه طلب می‌کند می‌رسد؛ اما میان دوستان جنگ و خصومت است.", "فرح": "زن خواستن، اما غم و اندوه هم می‌رسد؛ گم‌شده به نیکویی به دست می‌آید؛ زن حامله و زندانی را بد است؛ گریخته دشوار به دست می‌آید؛ روز سه‌شنبه آگاه می‌شود."}, "انکیس": {"طریق": "باطل شدن سفر و ناخوشی؛ مسافر بدحال است؛ غم و اندوه و زیان مال و گریختن بندگان و خیانت زیردستان؛ گفت‌وگو با مردم بداصل؛ چیزهای گران از دست می‌رود.", "عتبه الخارج": "غم و اندوه و بستگی کار و خصومت و مناظره و زیان مال از هر نوع؛ اگر سؤال از بیمار باشد بیم است؛ در سفر زیارت راحت می‌یابد اما در راه‌های دیگر بیم دزد و خطر است.", "لحیان": "سلامت تن و گشایش کارها و گرفتن مال؛ شرکت و ازدواج اصیل؛ معامله‌ی چهارپا نیک است؛ سفر و رسیدن غایب و همنشینی با دوستان.", "عقله": "کارهای بسته و بارهای بسته؛ عزم سفر؛ دعوی و مناظره و خیانت گواه؛ بیمار تا روز پنجشنبه در بیم است؛ زن حامله پسر می‌زاید؛ مال غایب و چهارپا به دست می‌آید.", "قبض الداخل": "سفر و گرفتن مال و چیزهای سرخ‌رنگ؛ اگر حمره در زایچه بسیار باشد زیان مال و خصومت است؛ غایب یا معشوق زود به هم می‌رسند.", "حمره": "گرفتن مال و سفر و زن خواستن و خریدن چهارپا نیک است؛ خصومت بر سر مال از سوی زنان و شریکان؛ اگر سؤال از دیدار باشد به هم می‌رسند؛ مشغولی به علم.", "قبض الخارج": "سفر و خصومت و غم و اندوه و زیان مال و بستگی کار؛ مردم بدکار؛ اگر سؤال از بیمار باشد بیم است؛ گریختن بندگان و خیانت زیردستان و تلف چهارپا.", "نقی الخد": "بدی عاقبت کارها؛ دل‌مشغولی و جدایی میان دوستان؛ اگر سؤال از دیدار باشد چیزی در آن نیست؛ سفر ناپسند است؛ به غایب غم و اندوه می‌رسد.", "جماعت": "سفر ناپسند و بی‌سود؛ زیان مال و گریختن بندگان و تلف چهارپایان؛ اگر سؤال از ازدواج باشد پسندیده نیست.", "انکیس": "جنگ و خصومت با مردم عامه و بداصل؛ اگر سؤال از غایب باشد کارش بی‌سامان است؛ بیماری و غم و اندوه و ستم پادشاه و بازخواست؛ روز یکشنبه آگاه می‌شود.", "عتبه الداخل": "مناظره با شخصی ناقص‌عضو بر سر مال یا به سبب زنی؛ زن حامله دشوار می‌زاید؛ با غایب جمع می‌شود؛ مشغولی به کارهای نیرنگ و طلسم.", "اجتماع": "به دست آوردن مال و جمع شدن با دوستان؛ غایب به سلامت است و خبرش زود می‌رسد؛ حرکت نیک است؛ معامله و سود و کار نیکوست؛ روز آدینه به مراد می‌رسد.", "بیاض": "رسیدن خبر و نامه از غایب و دوستان؛ خرید و فروش و کار نیکوست؛ دل‌مشغولی از سوی زنان و معشوق؛ نگرانی برای چیزی دزدیده یا گم‌شده چون جواهر سفید.", "نصره الداخل": "نیکویی عاقبت و گشایش کار و کسب و راحت از سوی دوستان؛ چهارپایی به دست می‌آید؛ سفر نیکوست و غایب به سلامت است؛ دلتنگی به خاطر بیماران.", "نصره الخارج": "نیکویی عاقبت و گشایش کارها و راحت از طرف بزرگان؛ هر امیدی دارد میسر می‌شود؛ سفر نیکوست و غایب به سلامت است؛ روز آدینه از احوال معشوق و دوستان آگاه می‌شود.", "فرح": "سلامت تن و نیکویی عاقبت؛ رسیدن به مقصود و مراد و کام دل؛ در سفر شادی و فرح از دوست می‌رسد؛ در دعوی و مناظره پیروز می‌شود؛ اما صاحب ضمیر اندکی ترسان است."}, "نصره الداخل": {"جماعت": "همنشینی با زنان و خریدن غلام و کنیز و چهارپا و گشایش کار؛ در دعوی و مناظره پیروز می‌شود؛ از دوستان و بزرگان راحت می‌بیند؛ پیوند و نکاح نیکوست.", "نصره الداخل": "سفر و حرکت و سلامت تن و راحت؛ غایب یا دوست عزیز زود می‌رسد؛ گم‌شده و گریخته به دست می‌آید؛ از پادشاه و یارانش خیر و راحت می‌بیند.", "انکیس": "دل‌مشغولی به خاطر بیمار یا کسی که در غم گرفتار است؛ خبر و نامه از غایب یا دوستی عزیز می‌رسد؛ دعوی و مناظره و گفت‌وگو با یکی از حاکمان.", "بیاض": "سلامت تن و عشرت با جماعت دوستان؛ بیماری دراز می‌کشد اما عاقبت بهبود می‌یابد؛ زیان چهارپا؛ از ترس و سردرد ایمن است.", "لحیان": "نیکویی احوال و گشایش کار و کسب؛ چهارپای گم‌شده به دست می‌آید؛ دعوی و مناظره به سبب زنان و غلام و کنیز؛ گلایه‌ی جماعت دوستان.", "نقی الخد": "مردی اندک‌ریش یا زنی سپیدپوست قصد مال دارد؛ غم و اندوه از این مردم؛ سفر خیر و راحتی ندارد؛ اما کالا و مال به دست می‌آید.", "حمره": "سفر و حرکت و نکاح دختر بکر؛ گم‌شده به دست می‌آید؛ روز شنبه از ضمیر آگاه می‌شود؛ گفت‌وگو بر سر گریخته و دزدیده؛ زن خواستن نیکوست.", "عتبه الداخل": "زیان مال و چهارپا و چیزهای سرخ چون جامه و زر و مس؛ زن حامله زود فارغ می‌شود؛ فروختن چهارپا نیک است؛ مأموران قصد مال دارند و تهمت در کار است.", "قبض الداخل": "گرفتن مال و رسیدن به مقصود و گشایش کارها به نیکی و عاقبت خوش؛ شادی از دیدار دوستان؛ بیمار پس از سختی کاملاً بهبود می‌یابد.", "اجتماع": "جمع شدن با زنان و دوستان در عیش و طرب؛ نیکویی کار و کسب؛ خریدن بهتر از فروختن است؛ رسیدن دوستان؛ سفر مبارک؛ زن خواستن و غایب هم نیکوست.", "فرح": "زیان مال و بستگی کارها و غم و اندوه از سوی زنان؛ تلف چهارپا؛ شکست جماعت دشمنان؛ و سرانجام بیرون آمدن از غم و اندوه.", "عتبه الخارج": "باطل شدن سفر و سرگردانی؛ غلام و کنیز می‌گریزند اما به دست می‌آیند؛ سوختن پوشاک یا دزدی؛ اما ازدواج نیکوست و عروسی و شادی هست.", "عقله": "زیان مال و بستگی کار و کسب؛ اما بیمار بهبود و زندانی و زن حامله رهایی می‌یابند؛ غم و اندوه و جدایی دوستان و یاران.", "قبض الخارج": "سفر؛ اگر سفر دریا باشد بیم است؛ طلب مال غایب؛ گفت‌وگو با زنان و شریکان به جدایی می‌کشد و میان دوستان دشمنی پیدا می‌شود.", "طریق": "سفر و حرکت و رسیدن نامه از غایب و آمدن دوستی؛ رسیدن به مرتبه‌ی بزرگی و پیروزی بر دشمن و گرفتن مال از بزرگان و گشایش کارها؛ اما میان زن و شوهر جدایی است.", "نصره الخارج": "زیان مال به سبب زنان و نزدیکان صاحب ضمیر؛ جدایی میان زن و شوهر؛ سفر نیکوست؛ نامه و پیغام از دوستان می‌رسد؛ کار پس از سختی گشوده می‌شود."}};
const MTH_GOOD = /خیر|گشایش|نیک|مبارک|سعادت|راحت|به مراد|مقصود|بهبود|سلامت|شادی|پیروز/g, MTH_BAD = /زیان|غم|اندوه|جنگ|خصومت|بیم|بستگی|نحس|ناپسند|بد |بدحال|دشوار|تلف|گریختن|باطل|ترس/g;
const mthTone = t => { const g = (t.match(MTH_GOOD) || []).length, b = (t.match(MTH_BAD) || []).length; return g > b + 1 ? 'good' : b > g + 1 ? 'bad' : 'mid'; };
const MTH_BASE = QUESTIONS.length;
QUESTIONS.push(
{ h: 15, q: 'حکم مثلثه‌ی شاهدان و قاضی (خانه‌های ۱۳، ۱۴ و ۱۵)', rule: 'شاهد راست (۱۳) و شاهد چپ (۱۴) و قاضی (۱۵) را یک «مثلثه» گیرند. برای هر قاضی بابی است با شانزده مثلثه، و هر مثلثه بر کاری دلالت دارد که سائل از آن می‌پرسد یا در آن است: کار و کسب، سفر، غایب، بیمار، زن و نکاح، مال و دزد و گم‌شده. در این باب‌ها جای شاهد راست و چپ مهم است: (الف و ب) با (ب و الف) دو حکم جداست.',
  run(){ const q = S(15), r = S(13), l = S(14), t = (MTH[q] || {})[r];
    if(!t) return [it('برای این مثلثه حکمی در جدول نیست.', [13, 14, 15], 'mid')];
    const out = [it(`شاهد راست «${r}»، شاهد چپ «${l}»، قاضی «${q}»: ${t}`, [13, 14, 15], mthTone(t))];
    const sw = MTH[q][l]; if(sw && l !== r) out.push(it(`اگر جای دو شاهد عوض می‌شد («${l}» راست و «${r}» چپ) حکم این بود: ${sw} این را برای مقایسه ببینید؛ حکم این رمل همان سطر اول است.`, [13, 14], 'info'));
    return out; } },
{ h: 15, q: 'این قاضی در کدام کارها نیک و در کدام بد است؟ (باب قاضی)', rule: 'شانزده مثلثه‌ی باب قاضی را مرور کنید: هر قاضی با هر جفت شاهد حکمی دارد. این‌جا همه‌ی حکم‌های باب همین قاضی آمده و سطر این رمل مشخص شده است، تا معلوم شود این قاضی بیشتر به چه کارهایی دلالت دارد.',
  run(){ const q = S(15), r = S(13), B = MTH[q] || {};
    return Object.entries(B).map(([a, t]) => it(`${a === r ? '<b>این رمل:</b> ' : ''}«${a}» و «${mul(a, q)}»: ${t}`, a === r ? [13, 14, 15] : [], a === r ? mthTone(t) : 'info')); } }
);
Q_TOPICS.push({ id: 'mth', ico: '🔺', t: 'مثلثات شاهدان و قاضی', d: 'حکم سه‌گانه‌ی شاهد راست، شاهد چپ و قاضی؛ ۲۵۶ مثلثه', s: [['مثلثه‌ی این رمل', [MTH_BASE]], ['باب قاضی', [MTH_BASE + 1]]] });

